@push('scripts')<script>(function(){async function copyText(value){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(value);return;}const helper=document.createElement('textarea');helper.value=value;helper.style.position='fixed';helper.style.opacity='0';document.body.appendChild(helper);helper.select();document.execCommand('copy');helper.remove();}document.querySelectorAll('[data-copy-raw]').forEach(function(button){button.addEventListener('click',async function(){try{await copyText(button.dataset.copyRaw);button.textContent='Copied';window.showToast?.('Invitation link copied');}catch(error){window.showToast?.('Copy failed. Select the link and copy it manually.');}});});document.querySelectorAll('[data-copy-invitation]').forEach(function(button){button.addEventListener('click',async function(){const original=button.textContent;button.disabled=true;button.textContent='Generating…';try{const response=await fetch(button.dataset.copyInvitation,{method:'POST',headers:{'X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,'Accept':'application/json'},credentials:'same-origin'});if(!response.ok) throw new Error('Request failed');const data=await response.json();if(!data.link) throw new Error('No link returned');await copyText(data.link);button.textContent='Copied fresh link';window.showToast?.('Fresh invitation link copied');}catch(error){button.textContent='Copy failed';window.showToast?.('Could not generate the invitation link.');}finally{window.setTimeout(function(){button.disabled=false;if(button.textContent==='Copy failed') button.textContent=original;},2200);}});});})();</script>@endpush
